// EAR OS · Finca Partnership Qualifier v9.0 · Split Soberano inmutable 80/10/10 (SSOT)
const SSOT = { baseSolista: 350.00, split: { artista: 0.80, earOs: 0.10, vimume: 0.10 }, deposito: 100.00 };
const body = $input.first().json.body ?? $input.first().json;
const required = ['fincaName', 'fincaLocation', 'contactName', 'contactPhone', 'capacity'];
const errores = required.filter(c => body[c] === undefined || body[c] === null || body[c] === '');
if (errores.length > 0) { return { valid: false, error: 'Faltan campos obligatorios: ' + errores.join(', ') }; }
const capacity = Number(body.capacity);
const weddingPackages = body.weddingPackages === true || body.weddingPackages === 'true';
const catering = body.catering === true || body.catering === 'true';
const greenArea = body.greenArea === true || body.greenArea === 'true';
let score = 0;
score += capacity >= 100 ? 30 : capacity >= 50 ? 20 : 10;
score += weddingPackages ? 25 : 0;
score += catering ? 20 : 0;
score += greenArea ? 15 : 0;
const loc = String(body.fincaLocation).toLowerCase();
score += (loc.includes('méntrida') || loc.includes('mentrida')) ? 10 : 5;
const tier = score >= 80 ? 'PLATINO' : score >= 60 ? 'ORO' : score >= 40 ? 'PLATA' : 'BRONCE';
const estimatedEvent = Number(body.estimatedEventPrice ?? SSOT.baseSolista);
return { valid: true, ...body, capacity, weddingPackages, catering, greenArea, score, tier, qualified: score >= 60, split: { artista: +(estimatedEvent * SSOT.split.artista).toFixed(2), earOs: +(estimatedEvent * SSOT.split.earOs).toFixed(2), vimume: +(estimatedEvent * SSOT.split.vimume).toFixed(2) }, fincaCommission: +(estimatedEvent * 0.10).toFixed(2), depositAmount: SSOT.deposito, requestId: body.requestId ?? ('FINCA-' + Date.now()) };

